package ais.action.master.jurnal.test;
import java.util.HashSet;import ais.action.master.jurnal.JurnalEmailTemplateCatalog;
public final class JurnalEmailCatalogDefinitionSelfTest{private JurnalEmailCatalogDefinitionSelfTest(){}public static void main(String[]a){if(JurnalEmailTemplateCatalog.KEYS.size()!=73||JurnalEmailTemplateCatalog.definitions().size()!=146)throw new IllegalStateException("Coverage default email bukan 73x2.");HashSet<String>ids=new HashSet<String>();for(JurnalEmailTemplateCatalog.Definition d:JurnalEmailTemplateCatalog.definitions()){if(!ids.add(d.key+"|"+d.locale)||d.subject.length()==0||d.body.length()==0)throw new IllegalStateException("Definition email invalid: "+d.key);for(String v:JurnalEmailTemplateCatalog.STANDARD_VARIABLES)if(d.subject.indexOf("{{"+v+"}}")<0&&d.body.indexOf("{{"+v+"}}")<0)throw new IllegalStateException("Variable tidak digunakan: "+d.key+"/"+v);}System.out.println("JurnalEmailCatalogDefinitionSelfTest OK keys=73 locales=146 safe-default-definitions");}}
